def get_movie(id, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0376000" if __import__("os").path.isdir("./environment_mix/0376000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        return dt.replace(microsecond=0).isoformat()

    def _parse_iso(s):
        if not s or not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    def _new_id(prefix):
        # time-sortable enough for local store; avoid extra deps
        ts = int(time.time() * 1000)
        return f"{prefix}_{ts}"

    start = time.time()
    now_dt = _now_utc()
    now_iso = _iso(now_dt)

    # --- Validate input ---
    if not isinstance(id, str) or not id.strip():
        # log even validation failures
        sr = _load("search_requests.json")
        if not isinstance(sr, list):
            sr = []
        sr_id = _new_id("srch")
        sr.append(
            {
                "id": sr_id,
                "api_key_id": None,
                "keyword_raw": "",
                "keyword_normalized": "",
                "status": "error",
                "result_count": None,
                "latency_ms": max(0, int((time.time() - start) * 1000)),
                "error_code": "validation_error",
                "error_message": "Invalid movie id parameter.",
                "created_at": now_iso,
                "updated_at": now_iso,
            }
        )
        _save("search_requests.json", sr)
        return _err("VALIDATION_ERROR", "id must be a non-empty string.", field="id")

    movies = _load("movies.json")
    if not isinstance(movies, list):
        movies = []

    movie = None
    for m in movies:
        if isinstance(m, dict) and m.get("id") == id:
            movie = m
            break

    # If not found by movie id but matches an API key id, treat as invalid reference in this endpoint.
    # This prevents confusing "not found" when the caller passed the wrong id type.
    if movie is None:
        keys = _load("api_keys.json")
        if isinstance(keys, list):
            for k in keys:
                if isinstance(k, dict) and k.get("id") == id:
                    # log as rejected request (observability)
                    sr = _load("search_requests.json")
                    if not isinstance(sr, list):
                        sr = []
                    sr_id = _new_id("srch")
                    sr.append(
                        {
                            "id": sr_id,
                            "api_key_id": k.get("id"),
                            "keyword_raw": "",
                            "keyword_normalized": "",
                            "status": "rejected",
                            "result_count": 0,
                            "latency_ms": max(0, int((time.time() - start) * 1000)),
                            "error_code": "invalid_reference",
                            "error_message": "Provided id looks like an API key id, not a movie id.",
                            "created_at": now_iso,
                            "updated_at": now_iso,
                        }
                    )
                    _save("search_requests.json", sr)
                    return _err("NOT_FOUND", "Movie not found.", id=id)
        # log not found as rejected for observability
        sr = _load("search_requests.json")
        if not isinstance(sr, list):
            sr = []
        sr_id = _new_id("srch")
        sr.append(
            {
                "id": sr_id,
                "api_key_id": None,
                "keyword_raw": "",
                "keyword_normalized": "",
                "status": "rejected",
                "result_count": 0,
                "latency_ms": max(0, int((time.time() - start) * 1000)),
                "error_code": "not_found",
                "error_message": "Movie not found.",
                "created_at": now_iso,
                "updated_at": now_iso,
            }
        )
        _save("search_requests.json", sr)
        return _err("NOT_FOUND", "Movie not found.", id=id)

    # Access rule: deleted records not accessible
    if movie.get("status") == "deleted":
        sr = _load("search_requests.json")
        if not isinstance(sr, list):
            sr = []
        sr_id = _new_id("srch")
        sr.append(
            {
                "id": sr_id,
                "api_key_id": None,
                "keyword_raw": "",
                "keyword_normalized": "",
                "status": "rejected",
                "result_count": 0,
                "latency_ms": max(0, int((time.time() - start) * 1000)),
                "error_code": "deleted",
                "error_message": "Movie is deleted.",
                "created_at": now_iso,
                "updated_at": now_iso,
            }
        )
        _save("search_requests.json", sr)
        return _err("NOT_FOUND", "Movie not found.", id=id)

    # Successful read should still be observable: record as fulfilled "request"
    sr = _load("search_requests.json")
    if not isinstance(sr, list):
        sr = []
    sr_id = _new_id("srch")
    sr.append(
        {
            "id": sr_id,
            "api_key_id": None,
            "keyword_raw": "",
            "keyword_normalized": "",
            "status": "fulfilled",
            "result_count": 1,
            "latency_ms": max(0, int((time.time() - start) * 1000)),
            "error_code": None,
            "error_message": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
    )
    _save("search_requests.json", sr)

    return {"movie": movie}

def create_movie(title, original_title=None, overview=None, release_year=None, language=None, popularity=None, status=None, **_extra):
    import json, os, datetime, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0376000" if __import__("os").path.isdir("./environment_mix/0376000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    # Validate inputs
    if not isinstance(title, str) or len(title.strip()) < 1:
        return _err("VALIDATION_ERROR", "title is required and must be a non-empty string.", field="title")
    if original_title is not None and not isinstance(original_title, str):
        return _err("VALIDATION_ERROR", "original_title must be a string.", field="original_title")
    if overview is not None and not isinstance(overview, str):
        return _err("VALIDATION_ERROR", "overview must be a string.", field="overview")
    if release_year is not None:
        if not isinstance(release_year, int):
            return _err("VALIDATION_ERROR", "release_year must be an integer.", field="release_year")
        # tool schema minimum 1800; datastore constraint allows 1878..2100 when present
        if release_year < 1800:
            return _err("VALIDATION_ERROR", "release_year must be >= 1800.", field="release_year")
        if release_year < 1878 or release_year > 2100:
            return _err("VALIDATION_ERROR", "release_year must be between 1878 and 2100 when provided.", field="release_year")
    if language is not None and not isinstance(language, str):
        return _err("VALIDATION_ERROR", "language must be a string.", field="language")
    if popularity is not None:
        if not isinstance(popularity, (int, float)) or isinstance(popularity, bool):
            return _err("VALIDATION_ERROR", "popularity must be a number.", field="popularity")
        if float(popularity) < 0:
            return _err("VALIDATION_ERROR", "popularity must be >= 0.", field="popularity")
        popularity = float(popularity)
    if status is None:
        status = "inactive"
    if not isinstance(status, str) or status not in ("active", "inactive"):
        return _err("VALIDATION_ERROR", "status must be one of: active, inactive.", field="status")

    movies = _load("movies.json")

    # Unique(title, release_year)
    t_norm = title.strip()
    for m in movies:
        if m.get("title") == t_norm and m.get("release_year") == release_year:
            return _err("CONFLICT", "A movie with the same title and release_year already exists.",
                        constraint="unique(title, release_year)")

    # Determine default popularity if not provided
    if popularity is None:
        popularity = 0.0

    now = _now()
    new_id = "mov_" + uuid.uuid4().hex

    row = {
        "id": new_id,
        "title": t_norm,
        "original_title": original_title,
        "overview": overview,
        "release_year": release_year,
        "language": language,
        "popularity": popularity,
        "status": status,
        "created_at": now,
        "updated_at": now
    }

    movies.append(row)
    _save("movies.json", movies)

    return {"movie": row}

def update_movie(id, title=None, original_title=None, overview=None, release_year=None, language=None, popularity=None, status=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0376000" if __import__("os").path.isdir("./environment_mix/0376000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        return dt.replace(microsecond=0).isoformat()

    def _new_id(prefix):
        ts = int(time.time() * 1000)
        return f"{prefix}_{ts}"

    start = time.time()
    now_dt = _now_utc()
    now_iso = _iso(now_dt)

    # ---- Validate inputs (schema + datastore constraints) ----
    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id is required and must be a non-empty string.", field="id")

    if title is not None and (not isinstance(title, str) or len(title) < 1):
        return _err("VALIDATION_ERROR", "title must be a non-empty string.", field="title")

    if original_title is not None and not isinstance(original_title, str):
        return _err("VALIDATION_ERROR", "original_title must be a string.", field="original_title")

    if overview is not None and not isinstance(overview, str):
        return _err("VALIDATION_ERROR", "overview must be a string.", field="overview")

    if release_year is not None:
        if not isinstance(release_year, int):
            return _err("VALIDATION_ERROR", "release_year must be an integer.", field="release_year")
        # Real catalog constraint
        if release_year < 1878 or release_year > 2100:
            return _err(
                "VALIDATION_ERROR",
                "release_year must be between 1878 and 2100 when provided.",
                field="release_year",
            )

    if language is not None and not isinstance(language, str):
        return _err("VALIDATION_ERROR", "language must be a string.", field="language")

    if popularity is not None:
        if not isinstance(popularity, (int, float)):
            return _err("VALIDATION_ERROR", "popularity must be a number.", field="popularity")
        if float(popularity) < 0:
            return _err("VALIDATION_ERROR", "popularity must be >= 0.", field="popularity")

    if status is not None:
        if status not in ("active", "inactive", "deleted"):
            return _err("VALIDATION_ERROR", "status must be one of: active, inactive, deleted.", field="status")

    movies = _load("movies.json")
    if not isinstance(movies, list):
        movies = []

    # Locate movie; if caller mistakenly passed an API key id, surface NOT_FOUND (movie) but don't mis-handle.
    idx = None
    for i, m in enumerate(movies):
        if isinstance(m, dict) and m.get("id") == id:
            idx = i
            break
    if idx is None:
        return _err("NOT_FOUND", "Movie not found.", id=id)

    movie = movies[idx]
    cur_status = movie.get("status")

    # Lifecycle transition enforcement
    transitions = {
        "active": {"inactive", "deleted"},
        "inactive": {"active", "deleted"},
        "deleted": set(),
    }
    if cur_status not in transitions:
        return _err("VALIDATION_ERROR", "Movie has invalid stored status.", id=id, status=cur_status)

    if status is not None and status != cur_status:
        if status not in transitions[cur_status]:
            return _err(
                "INVALID_TRANSITION",
                f"Illegal status transition {cur_status} -> {status}.",
                id=id,
                from_status=cur_status,
                to_status=status,
            )

    # If attempting to hard-delete: disallowed by rule; this tool only supports soft delete via status='deleted'.
    # There is no "hard delete" parameter; enforce referential constraint only if already deleted? Not needed.

    # Enforce unique(title, release_year) constraint if either changes and status won't be deleted (catalog keeps uniqueness across all rows typically)
    new_title = movie.get("title") if title is None else title
    new_release_year = movie.get("release_year") if release_year is None else release_year
    # Apply check only when both present (release_year nullable, but constraint states unique(title, release_year))
    for j, other in enumerate(movies):
        if j == idx or not isinstance(other, dict):
            continue
        if other.get("title") == new_title and other.get("release_year") == new_release_year:
            # If it's literally the same record, ignore; otherwise conflict
            return _err(
                "CONFLICT",
                "A movie with the same title and release_year already exists (unique(title, release_year)).",
                field="title",
            )

    # If changing to deleted, ensure no hard delete is performed; also keep record (soft delete).
    # Additionally, if the record is referenced by search_results, soft delete is allowed per rules.
    # Hard deletes are disallowed but not attempted here.

    # No-op detection: must still persist updated_at if any field actually changes? Real APIs typically no-op ok;
    # but "NO SUCCESS WITHOUT EFFECT": if nothing changes, treat as NOT_FOUND-equivalent? Better: VALIDATION_ERROR.
    # We'll require at least one mutable field provided that changes state/value.
    proposed = dict(movie)
    changed = False

    def _set(field, value):
        nonlocal changed
        if value is None:
            return
        if proposed.get(field) != value:
            proposed[field] = value
            changed = True

    _set("title", title)
    _set("original_title", original_title)
    _set("overview", overview)
    _set("release_year", release_year)
    _set("language", language)
    if popularity is not None:
        _set("popularity", float(popularity))
    _set("status", status)

    if not changed:
        return _err("VALIDATION_ERROR", "No changes requested.", id=id)

    proposed["updated_at"] = now_iso
    if "created_at" not in proposed or not proposed.get("created_at"):
        proposed["created_at"] = now_iso

    movies[idx] = proposed
    _save("movies.json", movies)

    # Observability: record operation in search_requests as an "error/rejected/fulfilled" surrogate log row.
    # Service has no dedicated audit table; search_requests is the only request log/counter table.
    sr = _load("search_requests.json")
    if not isinstance(sr, list):
        sr = []
    sr_id = _new_id("srch")
    sr.append(
        {
            "id": sr_id,
            "api_key_id": None,
            "keyword_raw": "update_movie",
            "keyword_normalized": "update_movie",
            "status": "fulfilled",
            "result_count": 1,
            "latency_ms": max(0, int((time.time() - start) * 1000)),
            "error_code": None,
            "error_message": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
    )
    _save("search_requests.json", sr)

    return {"movie": proposed}

def list_search_requests(api_key_id=None, status=None, created_at_from=None, created_at_to=None, error_code=None, page=None, page_size=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0376000" if __import__("os").path.isdir("./environment_mix/0376000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    # Defaults
    if page is None:
        page = 1
    if page_size is None:
        page_size = 50

    # Validate
    if api_key_id is not None and (not isinstance(api_key_id, str) or not api_key_id.strip()):
        return _err("VALIDATION_ERROR", "api_key_id must be a non-empty string.", field="api_key_id")
    if status is not None:
        if not isinstance(status, str) or status not in ("received", "fulfilled", "rejected", "error"):
            return _err("VALIDATION_ERROR", "status must be one of: received, fulfilled, rejected, error.", field="status")
    if error_code is not None and not isinstance(error_code, str):
        return _err("VALIDATION_ERROR", "error_code must be a string.", field="error_code")
    if not isinstance(page, int) or page < 1:
        return _err("VALIDATION_ERROR", "page must be an integer >= 1.", field="page")
    if not isinstance(page_size, int) or page_size < 1 or page_size > 200:
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 200.", field="page_size")

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            return _err("VALIDATION_ERROR", f"{field} must be an ISO 8601 date-time string.", field=field)
        try:
            # accept 'Z'
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return _err("VALIDATION_ERROR", f"{field} must be a valid ISO 8601 date-time.", field=field)

    dt_from = _parse_dt(created_at_from, "created_at_from")
    if isinstance(dt_from, dict) and "error" in dt_from:
        return dt_from
    dt_to = _parse_dt(created_at_to, "created_at_to")
    if isinstance(dt_to, dict) and "error" in dt_to:
        return dt_to
    if dt_from and dt_to and dt_from > dt_to:
        return _err("VALIDATION_ERROR", "created_at_from must be <= created_at_to.", field="created_at_from")

    rows = _load("search_requests.json")

    def _row_dt(row):
        s = row.get("created_at")
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    # Filter
    out = []
    for r in rows:
        if api_key_id is not None and r.get("api_key_id") != api_key_id:
            continue
        if status is not None and r.get("status") != status:
            continue
        if error_code is not None and r.get("error_code") != error_code:
            continue
        rdt = _row_dt(r)
        if dt_from is not None and rdt is not None and rdt < dt_from:
            continue
        if dt_to is not None and rdt is not None and rdt > dt_to:
            continue
        # If timestamps are malformed and filters require them, exclude conservatively
        if (dt_from is not None or dt_to is not None) and rdt is None:
            continue
        out.append(r)

    # Sort by created_at desc then id desc
    def _sort_key(r):
        rdt = _row_dt(r)
        # None sorts last
        if rdt is None:
            rdt = datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return (rdt, r.get("id") or "")
    out.sort(key=_sort_key, reverse=True)

    total = len(out)
    start = (page - 1) * page_size
    end = start + page_size
    page_rows = out[start:end]
    has_more = end < total

    return {
        "data": page_rows,
        "pagination": {
            "page": page,
            "page_size": page_size,
            "total": total,
            "has_more": has_more
        }
    }
